#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   ids        : [seq_len, n_axes=3] fp32  (per-axis positions)
//   theta      : scalar fp32  (RoPE base frequency)
//   freqs_cos  : [seq_len, total_dim=128] fp32 (DPS)
//   freqs_sin  : [seq_len, total_dim=128] fp32 (DPS)
//
// n_axes, axes_dim = [16, 56, 56], total_dim = 128 are all pinned by
// the problem definition. The single launcher invocation populates
// both outputs in parallel.
void run(
    const torch::Tensor& ids,
    double theta,
    torch::Tensor freqs_cos,
    torch::Tensor freqs_sin
) {
    TORCH_CHECK(ids.dim() == 2, "ids must be 2D [seq_len, n_axes]");
    TORCH_CHECK(freqs_cos.dim() == 2, "freqs_cos must be 2D");
    TORCH_CHECK(freqs_sin.dim() == 2, "freqs_sin must be 2D");

    constexpr int64_t kNumAxes = 3;
    constexpr int64_t kTotalDim = 128;
    TORCH_CHECK(ids.size(1) == kNumAxes,
                "ids must have ", kNumAxes,
                " axes, got ", ids.size(1));
    TORCH_CHECK(freqs_cos.size(1) == kTotalDim,
                "freqs_cos last dim must be ", kTotalDim,
                ", got ", freqs_cos.size(1));
    TORCH_CHECK(freqs_sin.size(1) == kTotalDim,
                "freqs_sin last dim must be ", kTotalDim,
                ", got ", freqs_sin.size(1));
    TORCH_CHECK(freqs_cos.size(0) == ids.size(0),
                "freqs_cos seq_len must match ids seq_len");
    TORCH_CHECK(freqs_sin.size(0) == ids.size(0),
                "freqs_sin seq_len must match ids seq_len");

    check_fp32_contiguous_cuda(ids, "ids");
    check_fp32_contiguous_cuda(freqs_cos, "freqs_cos");
    check_fp32_contiguous_cuda(freqs_sin, "freqs_sin");

    const float theta_f32 = static_cast<float>(theta);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_034_flux_multi_axis_rope_freq_launcher(
        ids, theta_f32, freqs_cos, freqs_sin, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 multi-axis RoPE frequency computation: generates cos/sin "
        "tables for FLUX 3D position encoding (axes_dim=[16,56,56], "
        "total_dim=128 pinned). Two distinct DPS outputs filled by "
        "one kernel launch.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// fp32 multi-axis RoPE frequency computation for FLUX 3D position
// encoding (time, height, width). Each output element is a
// pure-compute sin/cos of an angle whose construction depends on
// a single ids[s, axis] load plus an on-the-fly inverse-frequency
// table entry computed via `powf(theta, k / half_dim_axis)`.
//
// Grid: (seq_len,), one CTA per seq_len position. Each CTA has
// BLOCK_THREADS = total_dim = 128 (one thread per output d).
//
// Per-axis pinned constants (FLUX-Fill-dev):
//   axes_dim = {16, 56, 56},  total_dim = 128
//   axis_offset = {0, 16, 72}, half_dim = {8, 28, 28}
//
// Read traffic per CTA: 3 fp32 loads of ids[s, 0..2] (one broadcast
// per axis range across 16 / 56 / 56 threads respectively) plus
// the immediate `theta` constant. Output traffic dominates:
// 128 fp32 cos writes + 128 fp32 sin writes per CTA.

namespace {

constexpr int kNumAxes = 3;
constexpr int kTotalDim = 128;
constexpr int kBlockThreads = kTotalDim;

// Each thread maps its `d` in [0, 128) to (axis, pair_idx, half_dim_f).
// Compile-time constant axis spec (matches the FLUX-Fill-dev pin).
struct AxisSpec {
    int axis;
    int pair_idx;
    float half_dim_f;
};

__device__ inline AxisSpec resolve_axis(int d) {
    AxisSpec s;
    if (d < 16) {
        // axis 0: d in [0, 16), half_dim = 8
        s.axis = 0;
        s.pair_idx = d >> 1;
        s.half_dim_f = 8.0f;
    } else if (d < 72) {
        // axis 1: d in [16, 72), half_dim = 28
        s.axis = 1;
        s.pair_idx = (d - 16) >> 1;
        s.half_dim_f = 28.0f;
    } else {
        // axis 2: d in [72, 128), half_dim = 28
        s.axis = 2;
        s.pair_idx = (d - 72) >> 1;
        s.half_dim_f = 28.0f;
    }
    return s;
}

__global__ void __launch_bounds__(kBlockThreads, 8)
problem_034_rope_freq_kernel(
    const float* __restrict__ ids,
    float theta,
    float* __restrict__ freqs_cos,
    float* __restrict__ freqs_sin,
    int seq_len) {

    const int s = blockIdx.x;
    const int d = threadIdx.x;
    if (s >= seq_len) return;

    const AxisSpec spec = resolve_axis(d);

    // Read this row's axis position (broadcast across threads sharing
    // the same axis).
    const float axis_pos = ids[s * kNumAxes + spec.axis];

    // Compute freq_band on the fly:
    //   freq_band = 1.0 / theta^(pair_idx / half_dim)
    //             = exp(-(pair_idx / half_dim) * log(theta))
    // Using powf preserves the reference's numerics exactly.
    const float exponent = static_cast<float>(spec.pair_idx) / spec.half_dim_f;
    const float freq_band = 1.0f / powf(theta, exponent);

    const float angle = axis_pos * freq_band;
    const int out_offset = s * kTotalDim + d;
    freqs_cos[out_offset] = cosf(angle);
    freqs_sin[out_offset] = sinf(angle);
}

}  // namespace

void problem_034_flux_multi_axis_rope_freq_launcher(
    const torch::Tensor& ids,
    float theta,
    torch::Tensor& freqs_cos,
    torch::Tensor& freqs_sin,
    cudaStream_t stream) {

    const int seq_len = static_cast<int>(ids.size(0));

    dim3 grid(seq_len);
    dim3 block(kBlockThreads);

    problem_034_rope_freq_kernel<<<grid, block, 0, stream>>>(
        ids.data_ptr<float>(),
        theta,
        freqs_cos.data_ptr<float>(),
        freqs_sin.data_ptr<float>(),
        seq_len);
}

#pragma once

#ifndef PROBLEM_034_FLUX_MULTI_AXIS_ROPE_FREQ_KERNEL_H
#define PROBLEM_034_FLUX_MULTI_AXIS_ROPE_FREQ_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the fp32 multi-axis RoPE frequency kernel.
//
// Given ids of shape [seq_len, n_axes=3] fp32 and scalar theta,
// computes freqs_cos and freqs_sin both of shape [seq_len,
// total_dim=128] by independently running 1D RoPE per axis
// (axes_dim = [16, 56, 56]) and concatenating along the
// last dimension. For each axis a with axis_dim = 2 * half_dim_a:
//
//   freq_band[a, k] = 1.0 / theta^(k / half_dim_a)  for k in [0, half_dim_a)
//   angle[s, a, k]  = ids[s, a] * freq_band[a, k]
//   cos[s, axis_offset_a + 2*k]   = cos(angle[s, a, k])
//   cos[s, axis_offset_a + 2*k+1] = cos(angle[s, a, k])
//   sin[s, axis_offset_a + 2*k]   = sin(angle[s, a, k])
//   sin[s, axis_offset_a + 2*k+1] = sin(angle[s, a, k])
//
// (The repeat-by-2 along d-pairs comes from torch.repeat_interleave
// on the per-axis cos/sin outputs, then concatenation places the
// three axes' results contiguously: axis 0 occupies d in [0, 16),
// axis 1 occupies [16, 72), axis 2 occupies [72, 128).)
//
// One CTA per seq_len position, BLOCK_THREADS = total_dim = 128
// (one thread per output d element). Both outputs are filled by
// one kernel launch.
void problem_034_flux_multi_axis_rope_freq_launcher(
    const torch::Tensor& ids,
    float theta,
    torch::Tensor& freqs_cos,
    torch::Tensor& freqs_sin,
    cudaStream_t stream);

#endif  // PROBLEM_034_FLUX_MULTI_AXIS_ROPE_FREQ_KERNEL_H
